Crockett: I disagree. Derma-35 in fact causes inflammation, but in citing only the side effect of blemishes as the justification for its decision, the council rightly acknowledged that blemishes are a legitimate health concern.$batch07$ AND q.prompt=$batch07$Cox and Crockett disagree over whether$batch07$ AND q.correct_choice=$batch07$D$batch07$) THEN RAISE EXCEPTION 'Question changed: PT119-S2-Q1'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT119-S2-Q1$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT119-S2-Q1'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT119-S2-Q1$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Cox's Position$batch07$, $batch07$The council did not give sufficient justification for recalling Derma-35.$batch07$), (1, $batch07$Crockett's Position$batch07$, $batch07$"I disagree." The council cited blemishes, and it was right that blemishes are a legitimate health concern. So the justification was adequate.$batch07$), (2, $batch07$Evaluate$batch07$, $batch07$Crockett says "I disagree" right after Cox's only claim, so the disagreement is Cox's claim itself. Notice what Crockett does *not* do: Crockett mentions inflammation as a fact, but defends the council on blemishes alone.$batch07$), (3, $batch07$Goal$batch07$, $batch07$Whether the council's stated reason was enough to justify the recall.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT119-S2-Q1$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$Cox objects to the justification, not the recall itself. A decision can be right but poorly justified. So we don't know that Cox thinks the drug should stay on the market.$batch07$), ($batch07$B$batch07$, $batch07$Neither speaker connects blemishes to inflammation.$batch07$), ($batch07$C$batch07$, $batch07$Crockett says the council cited only blemishes. Cox never says what the council based its decision on.$batch07$), ($batch07$D$batch07$, $batch07$Cox: not "sufficient justification". Crockett: the council "rightly" relied on a legitimate concern. Adequate versus not.$batch07$), ($batch07$E$batch07$, $batch07$Crockett says Derma-35 causes inflammation but never says how serious inflammation is. Cox says nothing about it.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT119-S2-Q1$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
